using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsArchReview{
 [Serializable]class Probe{public string kind;public float x,y,z;public bool hit;}[Serializable]class Ground{public float x,y,z;}[Serializable]class Probes{public Probe[] probes;public Ground[] ground;}
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static void Shot(Camera c,Vector3 from,Vector3 target,string file){c.transform.position=from;c.transform.LookAt(target);var rt=new RenderTexture(960,720,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(960,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,960,720),0,0);t.Apply();File.WriteAllBytes(file,t.EncodeToPNG());RenderTexture.active=prev;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);}
 public static void Run(){const string ev="Evidence/Target25Arch";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget25Output/Room.unity");Physics.SyncTransforms();GameObject intact=GameObject.Find("ruins_22"),broken=GameObject.Find("ruins_25");Check(intact&&broken,"Formal arches missing");var objects=new[]{intact,broken};var data=JsonUtility.FromJson<Probes>(File.ReadAllText("Assets/Editor/arch-probes.json"));Check(data.probes.Length==2304,"Missing facade probes");float max=0;
 foreach(var p in data.probes){var go=p.kind=="arch"?intact:broken;var co=go.GetComponent<MeshCollider>();Check(co.sharedMesh==go.GetComponent<MeshFilter>().sharedMesh,"Visual/collision mesh identity");bool hit=co.Raycast(new Ray(go.transform.TransformPoint(new Vector3(p.x,p.y,-1)),go.transform.TransformDirection(Vector3.forward)),out var h,2);Check(hit==p.hit,"Arch opening mismatch "+p.kind+" "+p.x+","+p.y);if(hit){float delta=Mathf.Abs(go.transform.InverseTransformPoint(h.point).z-p.z);max=Mathf.Max(max,delta);Check(delta<.001,"Arch surface delta "+delta);}}
 Check(data.ground.Length>25,"Missing fallen-stone floor probes");foreach(var p in data.ground){var co=broken.GetComponent<MeshCollider>();Check(co.Raycast(new Ray(broken.transform.TransformPoint(new Vector3(p.x,2,p.z)),Vector3.down),out var hit,3),"Fallen stone missing");Check(Mathf.Abs(hit.point.y-broken.transform.position.y-p.y)<.001,"Fallen stone Web/native mismatch");}
 foreach(var go in objects){foreach(float x in new[]{-.6f,0,.6f}){var a=go.transform.TransformPoint(new Vector3(x,.35f,0));var b=go.transform.TransformPoint(new Vector3(x,1.35f,0));Check(!Physics.CheckCapsule(a,b,.25f),"Intended opening obstructed");}Check(Physics.CheckCapsule(go.transform.TransformPoint(new Vector3(1.2f,.35f,0)),go.transform.TransformPoint(new Vector3(1.2f,1.35f,0)),.2f),"Jamb fails to block");
 var actor=new GameObject("Arch walk diagnostic");actor.transform.position=go.transform.TransformPoint(new Vector3(0,.04f,-1.2f));var cc=actor.AddComponent<CharacterController>();cc.radius=.25f;cc.height=1.6f;cc.center=Vector3.up*.8f;cc.stepOffset=.3f;cc.skinWidth=.01f;cc.minMoveDistance=0;for(int i=0;i<24;i++)cc.Move(go.transform.TransformDirection(new Vector3(0,-.03f,.1f)));Check(go.transform.InverseTransformPoint(actor.transform.position).z>1.15,"Controller cannot traverse opening");UnityEngine.Object.DestroyImmediate(actor);}
 Check(intact.GetComponent<MeshCollider>().Raycast(new Ray(intact.transform.TransformPoint(new Vector3(0,1,0)),Vector3.up),out var crown,4),"Intact crown missing overhead");Check(!broken.GetComponent<MeshCollider>().Raycast(new Ray(broken.transform.TransformPoint(new Vector3(0,1,0)),Vector3.up),out var lost,4),"Broken crown has invisible collider");
 foreach(var template in objects){var clones=Enumerable.Range(0,9).Select(i=>{var g=UnityEngine.Object.Instantiate(template);g.transform.position=new Vector3(80+i*6,3,80);return g;}).ToArray();Check(clones.Select(g=>g.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(g=>g.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1&&clones.All(g=>g.GetComponent<MeshCollider>().sharedMesh==template.GetComponent<MeshFilter>().sharedMesh),"Arch reference sharing");foreach(var g in clones)UnityEngine.Object.DestroyImmediate(g);}
 var camera=UnityEngine.Object.FindAnyObjectByType<Camera>();camera.orthographic=false;camera.backgroundColor=new Color(.075f,.085f,.1f);RenderSettings.ambientLight=Color.gray*.75f;var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).First(l=>l.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);
 Shot(camera,intact.transform.TransformPoint(new Vector3(4.5f,4.8f,-6)),intact.transform.TransformPoint(new Vector3(0,1.7f,0)),ev+"/arch-close.png");Shot(camera,broken.transform.TransformPoint(new Vector3(4.5f,4.8f,-6)),broken.transform.TransformPoint(new Vector3(0,1.7f,0)),ev+"/broken-close.png");Shot(camera,new Vector3(17,20,18),new Vector3(2,4,0),ev+"/mixed-game.png");sun.transform.rotation=Quaternion.Euler(50,200,0);Shot(camera,intact.transform.TransformPoint(new Vector3(-4.5f,4.8f,6)),intact.transform.TransformPoint(new Vector3(0,1.7f,0)),ev+"/arch-back.png");
 var old=objects.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).ToArray();var gray=new Material(Shader.Find("Universal Render Pipeline/Lit"));gray.SetColor("_BaseColor",Color.gray);gray.SetFloat("_Smoothness",.15f);foreach(var o in objects)o.GetComponent<MeshRenderer>().sharedMaterial=gray;Shot(camera,intact.transform.TransformPoint(new Vector3(4.5f,4.8f,-6)),intact.transform.TransformPoint(new Vector3(0,1.7f,0)),ev+"/arch-mono.png");for(int i=0;i<2;i++)objects[i].GetComponent<MeshRenderer>().sharedMaterial=old[i];UnityEngine.Object.DestroyImmediate(gray);
 var hidden=broken.transform.parent.GetComponentsInChildren<MeshRenderer>().Where(r=>r.gameObject!=broken&&r.name!="TerrainCaps").ToArray();foreach(var r in hidden)r.enabled=false;sun.transform.rotation=Quaternion.Euler(38,-28,0);Shot(camera,broken.transform.TransformPoint(new Vector3(-3,3.8f,-5)),broken.transform.TransformPoint(new Vector3(0,1.6f,0)),ev+"/broken-isolated.png");Shot(camera,broken.transform.TransformPoint(new Vector3(3,2.8f,5)),broken.transform.TransformPoint(new Vector3(0,1,0)),ev+"/broken-back.png");foreach(var r in hidden)r.enabled=true;
 File.WriteAllText(ev+"/result.json","{\"pass\":true,\"formalKinds\":2,\"facadeAndOpeningProbes\":2304,\"maxDelta\":"+max.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"actualCharacterControllerTraversal\":true,\"jambBlocks\":true,\"intactCrownPresentBrokenCrownAbsent\":true,\"gpuMeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
